# shellcheck shell=bash
# The secret checked against the app's manifest before load-secrets (ADR 0053).
# scripts/secrets-manifest.json in the app repo, generated by secrets.sh, a key list per service:
#   {"api": ["DB_HOST", ...], "postiz": [...]}
# Keys in this service's list missing from the secret fail the deploy; keys the secret has
# beyond the list only warn. A service without a list is not checked (a warning).
# ADR 0020's {"services": {"<service>": {"required": [...], "optional": [...]}}} is read as its
# required keys until the project's first push writes the new form.
#
#   secrets_manifest_check <manifest> <secret json file> <service>

secrets_manifest_check() {
  local manifest=$1 secret=$2 service=$3 list missing extra
  # shellcheck disable=SC2016  # jq's $s
  list='if has("services") and (.services | type == "object")
        then (.services[$s] | if . == null then null else .required // [] end)
        else .[$s] end'
  jq -e 'type == "object"' "$manifest" >/dev/null 2>&1 \
    || { echo "secrets manifest: $manifest is not a JSON object" >&2; return 1; }
  if jq -e --arg s "$service" "$list | . == null" "$manifest" >/dev/null; then
    echo "secrets manifest: no key list for '$service' in $manifest (WARNING: not checked)" >&2
    return 0
  fi
  jq -e 'type == "object"' "$secret" >/dev/null 2>&1 \
    || { echo "secrets manifest: the secret is not a JSON object" >&2; return 1; }
  missing=$(jq -r --arg s "$service" --slurpfile sec "$secret" "($list) - (\$sec[0] | keys) | .[]" "$manifest")
  extra=$(jq -r --arg s "$service" --slurpfile sec "$secret" "(\$sec[0] | keys) - ($list) | .[]" "$manifest")
  if [[ -n $missing ]]; then
    echo "secrets manifest: keys missing from the secret for $service: $(paste -sd' ' <<<"$missing")" >&2
    echo "  push them to this environment's secret (scripts/secrets.sh <env> push <file> --service $service), then deploy again" >&2
    return 1
  fi
  if [[ -n $extra ]]; then
    echo "secrets manifest: WARNING: keys in the secret that $service's list doesn't name: $(paste -sd' ' <<<"$extra")" >&2
  fi
  echo "secrets manifest: ok ($service)"
}

# secrets_fetch <file>: the secret's JSON (key names and values) into <file>, mode 0600.
# Default: the AWS CLI with the app's profile; SECRETS_FETCH_CMD overrides (tests).
secrets_fetch() {
  local out=$1
  (umask 077; if [[ -n ${SECRETS_FETCH_CMD:-} ]]; then
    bash -c "$SECRETS_FETCH_CMD" >"$out"
  else
    aws secretsmanager get-secret-value --secret-id "${AWS_SM_SECRET_ID:?AWS_SM_SECRET_ID not set}" \
      --query SecretString --output text >"$out"
  fi)
}

# secrets_check <manifest> <service>: fetches the secret and checks it; no manifest only warns.
# Used by init_api.sh before load-secrets and by reload_secrets.sh.
secrets_check() {
  local manifest=$1 service=$2 secret rc=0
  if [[ ! -f $manifest ]]; then
    echo "secrets manifest: none at $manifest (WARNING: not checked)" >&2
    return 0
  fi
  secret=$(mktemp)
  secrets_fetch "$secret" && secrets_manifest_check "$manifest" "$secret" "$service" || rc=$?
  rm -f "$secret"
  return "$rc"
}
